const required = ['listSu01Users', 'getSu01UserDetail'];
const operations = Array.isArray($json.operations) ? $json.operations : [];
const missingOperations = required.filter((operation) => !operations.includes(operation));
return {
  readyForControlledBapiTest: $json.connected === true && $json.readOnly === true && missingOperations.length === 0,
  connected: $json.connected === true,
  readOnly: $json.readOnly === true,
  service: $json.service ?? 'unknown',
  version: $json.version ?? 'unknown',
  backend: $json.backend ?? null,
  missingOperations,
  remainingManualChecks: ['SE37 signature', 'S_RFC scope', 'S_USER_GRP scope', 'STAUTHTRACE positive and negative']
};
